from billing.validation import require_signature, require_account
from billing.results import Receipt

def acknowledge_notice(event, ledger, audit, accounts):
    require_signature(event)
    account = require_account(accounts, event.account_id)
    previous = ledger.lookup_delivery(event.delivery_key)
    if previous is not None:
        return Receipt(previous.invoice_id, previous.status, replayed=True)
    if event.currency != account.currency:
        raise ValueError("account currency mismatch")
    result = ledger.record_delivery(event.delivery_key, event.invoice_id,
                                    status="accepted", amount=event.amount)
    audit.append("notice_accepted", invoice_id=event.invoice_id)
    return Receipt(result.invoice_id, result.status, replayed=False)

def preview_notice(event, accounts):
    account = require_account(accounts, event.account_id)
    return {"display_id": event.trace_id, "account": account.label,
            "invoice": event.invoice_id, "amount": event.amount}

