from dataclasses import dataclass

@dataclass(frozen=True)
class DeliveryRow:
    invoice_id: str
    status: str
    amount: int

class Ledger:
    def __init__(self, database):
        self.database = database

    def lookup_delivery(self, delivery_key):
        return self.database.deliveries.get(delivery_key)

    def record_delivery(self, delivery_key, invoice_id, *, status, amount):
        row = DeliveryRow(invoice_id, status, amount)
        self.database.deliveries[delivery_key] = row
        self.database.flush()
        return row

    def mark_exported(self, invoice_id):
        self.database.exports.add(invoice_id)
        self.database.flush()

