def require_signature(event):
    if not event.signature_verified:
        raise ValueError("unverified notice")
    if event.amount < 0:
        raise ValueError("negative amount")

def require_account(accounts, account_id):
    account = accounts.get(account_id)
    if account is None or account.suspended:
        raise ValueError("account unavailable")
    return account

