from harbor.retries import may_reissue, next_retry

def schedule_due(attempts, policy, clock, queue):
    submitted = []
    for attempt in attempts:
        if not may_reissue(attempt, policy):
            continue
        due = next_retry(attempt, policy, clock)
        queue.put(attempt.identity, due=due)
        submitted.append(attempt.identity)
    return submitted

