class SigningKeyExpired(ValueError):
    pass

def seal_report(body, key, instant):
    if instant >= key.valid_until:
        raise SigningKeyExpired(key.identity)
    signature = key.sign(body)
    return {"body": body, "signature": signature, "key_id": key.identity}

def verify_envelope(envelope, keyring):
    key = keyring.by_id(envelope["key_id"])
    return key.verify(envelope["body"], envelope["signature"])

